"""Reviewer A's native D records for actually reviewed preimage page context."""
import hashlib
import json
from datetime import datetime, timezone
from pathlib import Path

D = Path(__file__).resolve().parent
ROOT = D.parents[6]
N = D / 'native20-preimage'

# Separately authored understanding/performance/transfer statements: DE/EN pairs.
EVIDENCE = [
 ('Artenvielfalt zählt verschiedene Arten; Individuenzahl, wissenschaftliche Neubeschreibung und weltweites Aussterben beschreiben unterschiedliche Sachverhalte.', 'Species diversity counts distinct species; individual counts, scientific new descriptions and global extinction describe different matters.', 'Die lernende Person benennt Artenbeispiele, ordnet die vorgegebene lokale Arten- und Individuenzahl ein und grenzt wissenschaftliche Entdeckung von persönlicher Erstbeobachtung ab.', 'The learner names species examples, interprets supplied local species and individual counts and distinguishes scientific discovery from a personal first sighting.', 'An einer anderen lokalen Liste mit andernorts fortbestehender Art wird lokales Verschwinden von globalem Aussterben abgegrenzt.', 'A different local inventory with a species surviving elsewhere is used to distinguish local disappearance from global extinction.'),
 ('Organstrukturen erfüllen bestimmte Funktionen und arbeiten im Säugetierkörper zusammen.', 'Organ structures perform specific functions and cooperate within the mammal body.', 'Die lernende Person verknüpft Knochen, Gelenke, Muskeln, Lunge, Herz und Haut mit passenden Bau-Funktions-Beziehungen.', 'The learner links bones, joints, muscles, lungs, heart and skin to suitable structure/function relationships.', 'Bei einem anderen Säugetier werden falsche Knochen-/Herzfunktionen anhand seines Organbaus begründet berichtigt.', 'For another mammal, incorrect bone/heart functions are corrected by reasoning from its organ structure.'),
 ('Säugetiermerkmale können unter bestimmten Umweltbedingungen Fortbewegung und Wärmehaushalt unterstützen.', 'Mammal traits can support locomotion and thermal balance under particular environmental conditions.', 'Die lernende Person erklärt die funktionelle Passung von Fell, Schwimmhaut oder Fettisolierung zu einem gegebenen Lebensraum.', 'The learner explains how fur, webbing or fat insulation functionally fit a supplied habitat.', 'An einem veränderten Säugetiermodell werden andere Merkmale funktionell gedeutet und absichtliche oder sofortige Umweltanpassung verworfen.', 'A changed mammal model is used to interpret different traits and reject intentional or instantaneous environmental adaptation.'),
 ('Ein Ethogramm trennt nachprüfbare Verhaltenskategorien und Zeitdaten von vorsichtiger Interpretation.', 'An ethogram separates reproducible behaviour categories and time data from cautious interpretation.', 'Die lernende Person beobachtet ein echtes geeignetes Tier beziehungsweise reales Video, definiert Kategorien und dokumentiert Verlauf und Unsicherheit.', 'The learner observes a suitable actual animal or genuine video, defines categories and records sequence and uncertainty.', 'Eine neue schonende Beobachtung wird mit nachvollziehbaren Kategorien ausgewertet; Gefühle oder Absichten werden nicht aus einer Einzelbewegung sicher behauptet.', 'A new nonintrusive observation is analysed with reproducible categories; feelings or intentions are not asserted as certain from a single movement.'),
 ('Domestikation und Zucht verändern vererbbare Merkmale verwandter Populationen über Generationen.', 'Domestication and breeding alter inherited traits in related populations across generations.', 'Die lernende Person beschreibt Abstammung des Hundes und menschliche Auswahl von Zuchtmerkmalen und unterscheidet diese von Erziehung eines Individuums.', 'The learner describes dog ancestry and human selection of breeding traits and distinguishes them from individual training.', 'Ein neuer Vergleich von Hundelinien wird als Populationsgeschichte gedeutet, ohne Körpergröße als höhere Entwicklungsstufe auszugeben.', 'A new dog-line comparison is interpreted as population history without treating body size as a higher developmental rank.'),
 ('Geeignete Wasser-, Temperatur- und Sauerstoffbedingungen unterstützen Keimung; anschließendes Wachstum wird zeitlich dokumentiert.', 'Suitable water, temperature and oxygen conditions support germination; subsequent growth is recorded over time.', 'Die lernende Person beschreibt Bedingungen und dokumentiert bei einer angeleiteten echten Samenbeobachtung Keimwurzel, Spross und Blattentwicklung.', 'The learner describes conditions and records radicle, shoot and leaf development in guided observation of real seeds.', 'In einer neuen Beobachtungsreihe werden Bedingungen und Wachstumsmerkmale verglichen; synthetische Werte bleiben von eigenen Messungen getrennt.', 'A new observation series compares conditions and growth features; synthetic figures remain distinct from personal measurements.'),
 ('Wurzel, Spross und Blatt wirken bei Wasseraufnahme, Stoffbildung und Stofftransport als zusammenhängendes Organsystem.', 'Root, stem and leaf cooperate as a connected organ system for water uptake, substance production and transport.', 'Die lernende Person erklärt Aufnahme, Stütz-/Leitfunktion sowie Blattfotosynthese und Transpiration an einer Blütenpflanze.', 'The learner explains uptake, support/conduction, leaf photosynthesis and transpiration in a flowering plant.', 'Bei einer Pflanze mit Speicherwurzel werden Wassertransport und Assimilattransport nach ihren jeweiligen Quellen und Senken unterschieden.', 'For a plant with a storage root, water and assimilate transport are distinguished by their respective sources and sinks.'),
 ('Blütenbestandteile erfüllen Schutz-, Bestäubungs- und Fortpflanzungsfunktionen; Bestäubung ist von Befruchtung verschieden.', 'Flower parts perform protective, pollination and reproductive functions; pollination differs from fertilization.', 'Die lernende Person benennt Kelch, Krone, Staubblätter und Stempelbestandteile und erläutert Samen-/Fruchtbildung aus ihren jeweiligen Ausgangsstrukturen.', 'The learner names sepals, petals, stamens and pistil parts and explains seed/fruit formation from their respective starting structures.', 'An einer anders bestäubten Blüte werden fehlende bunte Kronblätter funktionell erklärt und Pollen, Befruchtung, Samen und Frucht weiterhin getrennt.', 'For a differently pollinated flower, absence of colourful petals is functionally explained while pollen, fertilization, seed and fruit remain distinct.'),
 ('Einfache Bestimmungsmerkmale erlauben eine begrenzte begründete Zuordnung; Wildvorkommen und Nutzung sind verschiedene Kriterien.', 'Simple identification traits support bounded reasoned assignments; wild occurrence and human use are distinct criteria.', 'Die lernende Person ordnet unbekannte Pflanzen anhand beobachtbarer Merkmale und eines geeigneten begrenzten Schlüssels zu und erklärt ihren Entscheidungsweg.', 'The learner identifies unknown plants using observable traits and an appropriate bounded key and explains the decision path.', 'Ein veränderter Pflanzen-/Blattsatz wird ohne vorgegebene Objekt-Namens-Lösungen bestimmt; Nutzung derselben Art und Grenzen einzelner Merkmale werden erläutert.', 'A changed plant/leaf set is identified without supplied object/name solutions; use of the same species and limits of single traits are explained.'),
 ('Bau- und Funktionsmerkmale haben unter bestimmten Lebensraumbedingungen unterschiedliche Vorteile, ohne absichtliche individuelle Neubildung.', 'Structural and functional traits provide different benefits under particular habitat conditions without intentional individual production.', 'Die lernende Person deutet Flügel/Federn, Bewegungsorgane oder andere vorgegebene Merkmale funktionell bezogen auf Luft, Wasser oder Land.', 'The learner interprets wings/feathers, movement structures or other supplied traits functionally in relation to air, water or land.', 'Bei einem anderen Vogel oder der bedingt gewählten anderen Tierklasse werden funktionelle Unterschiede begründet und pauschale Aussagen über alle Vertreter begrenzt.', 'For another bird or the conditionally selected other animal class, functional differences are justified and blanket statements about all members are bounded.'),
 ('Revier, Partnerwerbung, Paarung und Brutpflege bilden zusammen bedingte Fortpflanzungsstrategien.', 'Territories, mate attraction, mating and brood care together form conditional reproductive strategies.', 'Die lernende Person vergleicht vorgegebene Vogelstrategien anhand Revier-/Balzverhalten, Paarung und Pflegeaufwand je Nachkomme.', 'The learner compares supplied bird strategies by territorial/courtship behaviour, mating and per-offspring care investment.', 'Ein neuer kolonialer oder bedingt gewählter Fischfall wird verglichen, ohne fehlende Pflege oder eine universell beste Strategie zu behaupten.', 'A new colonial or conditionally selected fish case is compared without asserting absent care or a universally superior strategy.'),
 ('Leichtbau verbindet geringe Masse mit Stabilität; verschiedene Federtypen besitzen Flug-, Wärme- und Schutzfunktionen.', 'Lightweight construction combines low mass with stability; different feather types serve flight, thermal and protective functions.', 'Die lernende Person erklärt Verstrebung im Vogelskelett und den Zusammenhang von Schaft, Ästen und zusammenhängender Fahne mit geeigneten Funktionen.', 'The learner explains bird-skeleton bracing and relates shaft, branches and a continuous vane to suitable functions.', 'Bei einer beschädigten Fahne beziehungsweise einem nichtfliegenden Vogel werden andere Funktionsbeiträge erläutert statt universelle Flugfähigkeit aus Federn abzuleiten.', 'For a damaged vane or flightless bird, differing functional contributions are explained instead of inferring universal flight from feathers.'),
 ('Stromlinienform, Kiemen und Schwimmblase beeinflussen Widerstand, Gasaustausch und Auftrieb in unterschiedlichen Mechanismen.', 'Streamlining, gills and swim bladder affect drag, gas exchange and buoyancy through different mechanisms.', 'Die lernende Person beschreibt die drei Strukturen und ordnet ihre Funktionen am vorgegebenen Knochenfischmodell getrennt zu.', 'The learner describes the three structures and separately assigns their functions in the supplied bony-fish model.', 'Bei bedingt verändertem Gasvolumen und Körperform wird eine Auftriebsänderung von Kiemengasaustausch getrennt; Fische ohne Schwimmblase bleiben möglich.', 'With conditionally altered gas volume and body shape, buoyancy change is separated from gill exchange; fish without swim bladders remain possible.'),
 ('Eierlegende Reptilien und Vögel teilen eine geschützte dotterversorgte Embryonalentwicklung, unterscheiden sich aber in den gegebenen Pflegebedingungen.', 'Egg-laying reptiles and birds share protected yolk-supported embryonic development but differ in the supplied care conditions.', 'Die lernende Person beschreibt Befruchtung, Embryonalentwicklung, Schlupf und weiteres Wachstum und vergleicht die beiden vorgegebenen Beispiele.', 'The learner describes fertilization, embryonic development, hatching and further growth and compares the two supplied examples.', 'Ein verändertes Fehlerschema mit Kiemenlarve oder sofort erwachsenem Jungtier wird korrigiert und lebendgebärende Reptilienausnahmen werden berücksichtigt.', 'A changed faulty scheme showing gilled larvae or immediately adult hatchlings is corrected while live-bearing reptile exceptions are respected.'),
 ('Wechselwarme Tiere beeinflussen ihre Körpertemperatur durch Verhalten und äußeren Wärmeaustausch innerhalb von Umweltgrenzen.', 'Ectothermic animals influence body temperature through behaviour and external heat exchange within environmental limits.', 'Die lernende Person erklärt geeignete Sonnen-, Schatten-, Haltungs- und Ortswechselstrategien in einem gegebenen Tagesverlauf.', 'The learner explains suitable basking, shade, posture and site-choice strategies in a supplied daily course.', 'Bei anderen oder gleichmäßig kühlen Umgebungsbedingungen wird erklärt, warum Ortswechsel fehlende Wärme nicht erzeugt und Aktivität begrenzt bleiben kann.', 'Under changed or uniformly cool conditions, the learner explains why movement cannot create absent heat and activity may remain limited.'),
 ('Das thermisch empfindliche Grubenorgan bestimmter Schlangen liefert Infrarotkontrasthinweise ergänzend zur visuellen Information.', 'The thermally sensitive pit organ of particular snakes supplies infrared-contrast cues in addition to visual information.', 'Die lernende Person erklärt Lage, Membranreaktion und räumliche Orientierungshilfe des Klapperschlangenorgans sowie die Zusammenarbeit mit dem Auge.', 'The learner explains location, membrane response and spatial orientation cues of the rattlesnake organ and its cooperation with the eye.', 'Bei veränderten Licht- und Temperaturkontrasten werden die unterschiedlichen Beiträge begründet, ohne perfekte Bildgebung oder ein Organ aller Schlangen zu behaupten.', 'Under changed light and thermal contrasts, differing contributions are justified without asserting perfect imaging or an organ in all snakes.'),
 ('Feuchte durchblutete Haut und belüftete Lungen ermöglichen bedingten Sauerstoff-/Kohlendioxidaustausch bei Amphibien.', 'Moist perfused skin and ventilated lungs enable conditional oxygen/carbon-dioxide exchange in amphibians.', 'Die lernende Person erklärt Diffusionsflächen, Stoffgefälle, Durchblutung und Mundbodenpumpen-Ventilation beim vorgegebenen erwachsenen Frosch.', 'The learner explains diffusion surfaces, gradients, perfusion and mouth-floor ventilation in the supplied adult frog.', 'An einem hypothetischen Unterwasser-/Trockenheitsfall werden Beiträge und Grenzen verglichen, ohne unbegrenzte Tauchdauer oder einen eigenen Belastungsversuch zu behaupten.', 'A hypothetical underwater/drying case is used to compare contributions and limits without asserting unlimited dives or a personal stress experiment.'),
 ('Schilddrüsenhormone wirken als zeitliche Steuersignale der Metamorphose und nicht als direktes Baumaterial der Organe.', 'Thyroid hormones act as timing signals for metamorphosis rather than direct building material for organs.', 'Die lernende Person deutet vorgelegte Entwicklungsvergleiche bei verminderter und wiederhergestellter Hormonwirkung mit Kontrolle und begrenzter Kausalaussage.', 'The learner interprets supplied developmental comparisons with reduced/restored hormone action, controls and bounded causal claims.', 'Ein anderer Stadien-/Signalzeitvergleich wird mit individuellen Unterschieden erläutert; stärkere Signale werden nicht mit unbegrenzt besserer Entwicklung gleichgesetzt.', 'A changed stage/signalling-time comparison is explained with individual differences; stronger signals are not equated with unlimited better development.'),
 ('Eizahl und Brutpflegeform verteilen elterliche Investition unterschiedlich und garantieren keine universelle Erfolgsrangfolge.', 'Egg number and brood-care form distribute parental investment differently without guaranteeing a universal success ranking.', 'Die lernende Person vergleicht unbewachte Wasser-Eier, Tragen oder Bewachen hinsichtlich Eizahl, Schutz und Aufwand.', 'The learner compares unguarded aquatic eggs, carrying or guarding by egg count, protection and investment.', 'Im neuen bedingten Zahlenmodell werden Überlebensanteil und absolute erwartete Überlebendenzahl korrekt unterschieden und von realen Artwerten abgegrenzt.', 'In a new conditional numerical model, survival fraction and absolute expected survivor counts are correctly distinguished and separated from real species figures.'),
 ('Haltungsanforderungen folgen artspezifischen physiologischen und Verhaltensbedürfnissen und müssen zuverlässig umgesetzt werden.', 'Husbandry requirements follow species-specific physiological and behavioural needs and must be implemented reliably.', 'Die lernende Person beurteilt konkrete Pläne anhand Nahrung/Wasser, Raum, Sozial-/Ruhebedarf, Rückzug, Pflege und organisierter Betreuung.', 'The learner assesses specific plans by food/water, space, social/rest needs, refuge, care and arranged supervision.', 'Ein Plan für eine andere Tierart wird neu geprüft statt unverändert übertragen; artspezifische Informationen und Ruhe-/Aktivitätszeiten führen die Anwendung.', 'A plan for another animal species is reassessed rather than transferred unchanged; species-specific information and rest/activity times guide application.'),
]

def sha(p):
    return 'sha256:' + hashlib.sha256(p.read_bytes()).hexdigest()

campaign = json.loads((N / 'round-a/description-review-campaign.json').read_text())
actual = json.loads((N / 'round-a/description-review-input.json').read_text())
science = json.loads((D / 'twenty-whole-goal-science.first.actual.json').read_text())
assert [g['goalId'] for g in actual['goals']] == [g['goalId'] for g in science['goals']]
assert len(EVIDENCE) == 20
batch = campaign['batches'][0]
run_id = 'biologie-flora-fauna20-native-preimage-independent-a-20261007-v1'
records = []
for g, s, e in zip(actual['goals'], science['goals'], EVIDENCE):
    records.append({
        '$schema': 'https://skillpilot.com/schemas/goal-description-review/v1/goal-description-review-record.schema.json',
        'schemaVersion': 1, 'recordId': run_id + '.' + g['goalId'], 'runId': run_id,
        'campaignId': campaign['campaignId'], 'roundId': campaign['roundId'],
        'bundleFingerprint': actual['bundleFingerprint'], 'bookDigest': actual['bookDigest'],
        **{k: g[k] for k in ['goalId', 'goalFingerprint', 'pageFingerprint', 'currentTitleDe', 'currentTitleEn', 'currentDescriptionDe', 'currentDescriptionEn']},
        'decision': 'keep',
        'understandingEvidence': dict(zip(['essentialUnderstandingDe', 'essentialUnderstandingEn', 'observablePerformanceDe', 'observablePerformanceEn', 'transferExpectationDe', 'transferExpectationEn'], e)),
        'rationale': s['descriptionAndAtomicityObservationDe'] + ' ' + s['wholeFortyCaseScientificObservationDe'] + ' Originalabschnitt ' + s['primarySectionActuallyRead'] + ' vollständig gelesen. Aktuelle native Vorbild-Buchkontexte/Beziehungen separat geprüft; Bilder fehlen, finale Raster-/Seitenbindungen bleiben offen. Keine menschliche Freigabe oder reale Lernendenleistung.',
        'evidenceProfileContract': 'positive-understanding-evidence-v2',
        'evidenceProfileRecommendation': 'revise' if s['findings'] else 'create',
        'recordStatus': 'candidate', 'reviewAuthority': 'ai_candidate',
    })

out = N / 'round-a/results'
records_path = out / (batch['batchId'] + '.records.jsonl')
records_text = ''.join(json.dumps(r, ensure_ascii=False, separators=(',', ':')) + '\n' for r in records)
if records_path.exists():
    assert records_path.read_text() == records_text, 'Existing independent records must stay exact'
else:
    with records_path.open('x', encoding='utf-8') as f:
        f.write(records_text)
bundle = json.loads((N / 'bundle/manifest.json').read_text())
run = {
    '$schema': 'https://skillpilot.com/schemas/goal-evidence/v1/goal-evidence-ai-run-manifest.schema.json',
    'schemaVersion': 1, 'runId': run_id, 'campaignId': campaign['campaignId'],
    'roundId': campaign['roundId'], 'batchId': batch['batchId'],
    'batchInputFingerprint': batch['batchInputFingerprint'],
    'bundleFingerprint': actual['bundleFingerprint'], 'bookDigest': actual['bookDigest'],
    'provider': 'OpenAI', 'model': 'Codex independent A; exact serving model revision not exposed',
    'role': 'subject_reviewer', 'promptFamilyId': 'goal-description-understanding-evidence-v2',
    'promptFingerprint': campaign['promptFingerprint'], 'criteriaFingerprint': campaign['criteriaFingerprint'],
    'generationParametersFingerprint': 'sha256:' + hashlib.sha256(b'Independent Codex A source/case/description review; serving sampling parameters unavailable').hexdigest(),
    'independenceGroupId': campaign['independenceGroupId'], 'blindToOtherRuns': True,
    'goalIds': batch['goalIds'],
    'inputArtifacts': [{'role': f['role'], 'digest': f['digest']} for f in bundle['artifacts'] if f['role'] in ['book_model', 'book_pdf', 'book_pdf_render_manifest', 'review_input_json', 'review_prompt', 'review_criteria']],
    'startedAt': science['recordedAt'], 'completedAt': datetime.now(timezone.utc).isoformat(),
    'outputDigest': sha(records_path), 'status': 'completed',
    'toolchainVersion': 'skillpilot-goal-description-review-v1',
}
run['inputArtifacts'].append({'role': 'description_review_batch_input_jsonl', 'digest': batch['batchInputFingerprint']})
with (out / (batch['batchId'] + '.run.json')).open('x', encoding='utf-8') as f:
    f.write(json.dumps(run, ensure_ascii=False, indent=2) + '\n')
print('Native D20 preimage A records written:20KEEP,18createP,2reviseP; no final image approval.')
